__NUXT_JSONP__("/finanzas-publicas/eventos/el_impuesto_predial_es_clave_para_impulsar_el_desarrollo_sostenible_de_las_ciudades", (function(a,b,c,d,e){return {data:[{post:{slug:"el_impuesto_predial_es_clave_para_impulsar_el_desarrollo_sostenible_de_las_ciudades",title:"El impuesto predial es clave para impulsar el desarrollo sostenible de las ciudades",date:"2024-11-19T22:24:57.711Z",img:"https:\u002F\u002Fucarecdn.com\u002Fad1ef2a0-f7bd-453b-b0c5-20570d6051d7\u002F","img-alt":"Liliana Alvarado",autor:"Ethos",category:"finanzas-publicas",extracto:"Liliana Alvarado, directora  de Ethos, participó en el Summit 2024 «Ciudades con futuro. Sin miedo a la acción», del Foro Mar de Cortés, en el cual compartió una conferencia sobre la importancia de incrementar la recaudación del impuesto predial para impulsar el desarrollo sostenible de las ciudades.",toc:[],body:{type:"root",children:[{type:b,tag:c,props:{},children:[{type:a,value:"La directora de Ethos, Liliana Alvarado, participó en el Summit 2024 «Ciudades con futuro. Sin miedo a la acción», del Foro Mar de Cortés, con la conferencia “Financiamiento para el desarrollo urbano: análisis del caso específico del impuesto predial”. En ella destacó que es fundamental que estados y municipios fortalezcan sus ingresos propios para mejorar sus servicios públicos e infraestructura y así impulsar el desarrollo sostenible de las ciudades. Esto, dijo, se puede lograr mejorando la recaudación del impuesto predial. "}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Liliana indicó que en 2023, las aportaciones y participaciones federales representaron 72% de los ingresos totales de los municipios, recordando que la dependencia de los estados es mayor, al ser de un 82 por ciento. Mientras que en la región del Mar de Cortés, hay estados destacados en la recaudación del predial, como Baja California, que ocupa el octavo lugar a nivel nacional en ingresos propios. Aunque también hay entidades con bajos niveles de recaudación, como Nayarit, que se ubicó en el último lugar en 2023 con apenas 403 millones de pesos."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Pero, ¿cómo se puede incrementar la recaudación del predial? Alvarado puntualizó que es clave la actualización de los catastros a precios de mercado, y para que sea con mayor celeridad, es recomendable reducir el número de actores involucrados en el proceso de actualización de las tablas de valores de suelo y construcción; establecer periodos anuales para la actualización y sanciones por incumplimiento y hacer un mayor uso de la tecnología."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Por otro lado, dijo que hace falta motivar la celebración de convenios de colaboración entre estados y municipios para ayudar a estos últimos en las tareas de recaudación. No obstante, para que los convenios no resulten desventajosos para los municipios deben tener ciertos elementos mínimos, como contar con mecanismos de transparencia y rendición de cuentas. "}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Y otro tema que se debe atender es la revisión de tratamientos preferenciales, su reducción y, en el caso de poblaciones vulnerables como adultos mayores, pensionados, jubilados, personas con discapacidad, madres solteras, entre otras, explorar la posibilidad de apoyarlas vía gasto directo. Y facilitar el pago de este impuesto, pues existen municipios donde los contribuyentes deben pagar en efectivo directamente en oficinas municipales."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Finalmente, puntualizó que “todas las mejoras en la gestión del predial serán implementadas con mayor éxito si también se invierte en la profesionalización y la capacitación de los servidores públicos municipales que estarán a cargo de estos sistemas de gestión catastral”."}]}]},dir:"\u002Feventos",path:"\u002Feventos\u002Fel_impuesto_predial_es_clave_para_impulsar_el_desarrollo_sostenible_de_las_ciudades",extension:".md",createdAt:e,updatedAt:e}}],fetch:{},mutations:[]}}("text","element","p","\n","2025-04-23T06:21:15.372Z")));